var supersetUrl = "https://" + context.grafana.replaceVariables("${maya_ui_url}") + "/postaci/api/v1/export/pdf";

window.resetUI = function () {
    $("#btnExport").removeAttr('disabled');
    $("#btnExport").html('Export');
};
window.startDown = function () {
    $("#btnExport").attr('disabled', 'disabled');
    $("#btnExport").html('Working...');
    $("#pfdReady").css({ 'display': 'none' });
    $("#pfdReady").attr('href', '');
};

window.getPDF = function () {
    var href = URL.parse(window.location.href);
    href.searchParams.delete('kiosk');
    var entries = href.searchParams.entries();
    let l = href.origin + href.pathname + '?';
    for (let n = entries.next(); !n.done; n = entries.next()) {
        let name = n.value[0];
        if (!name.startsWith('var-view_')
            && !name.startsWith('var-top_')
            && !name.startsWith('var-all_')
            && !name.startsWith('var-auth_')) {
            l = l + '&' + (name + (n.value.length > 1 ? '=' + encodeURIComponent(n.value[1]) : ''));
        }
    }
    l = l + '&pdf-export=true';

    fetch('/postaci/api/v1/export/pdf', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            url: l + "&t=" + new Date().getTime() + "&kiosk",
            emails: "",
            export_format: $('#cmbType').val()
        })
    })
        .then(async (res) => {
            if (!res.ok) {
                window.resetUI();
                const text = await res.text();
                throw new Error(`Export failed (${res.status}): ${text}`);
            }
            const ct = res.headers.get("content-type") || "";
            if (!ct.includes("application/pdf") && !ct.includes("image/png")) {
                window.resetUI();
                const text = await res.text();
                throw new Error("Expected PDF/PNG but got: " + ct + "\n" + text);
            }
            window.resetUI();
            return res.blob();
        })
        .then(blob => {
            const pdfUrl = URL.createObjectURL(blob);
            $("#pfdReady").css({ 'display': '' });
            $("#pfdReady").attr('href', pdfUrl);
            window.open(pdfUrl, '_blank');
            setTimeout(() => URL.revokeObjectURL(pdfUrl), 300_000);
        })
        .catch(err => {
            window.resetUI();
            console.error("PDF export error:", err);
            alert("PDF export failed:\n" + err.message);
        });
};

// ---------- CSV option: detect single-table dashboards ----------

window.findTablePanels = function () {
    // Grafana tableng uses react-data-grid: role="grid" + .rdg class.
    // Scoped to dashboard grid items so the Business Text panel is ignored.
    var grids = document.querySelectorAll('.react-grid-item [role="grid"].rdg');
    var panels = [];
    grids.forEach(function (g) {
        var p = g.closest('.react-grid-item');
        if (p && panels.indexOf(p) === -1) panels.push(p);
    });
    // Deterministic order: top-to-bottom, left-to-right.
    panels.sort(function (a, b) {
        var ra = a.getBoundingClientRect(), rb = b.getBoundingClientRect();
        return (ra.top - rb.top) || (ra.left - rb.left);
    });
    return panels;
};

window.exportTableCSV = function () {
    var panels = window.findTablePanels();
    if (panels.length < 1) {
        window.resetUI();
        alert('CSV export requires at least one table panel on the dashboard.');
        return;
    }
    var panel = panels[0];
    var tableEl = panel.querySelector('[role="grid"].rdg');

    // Header cells live inside .rdg-header-row; each has <span> label + filter button (SVG only, no text).
    var headers = Array.prototype.map.call(
        tableEl.querySelectorAll('.rdg-header-row [role="columnheader"]'),
        function (h) {
            var label = h.querySelector('span');
            return (label ? label.textContent : h.textContent).trim();
        }
    );

    // Data rows are .rdg-row (header row is .rdg-header-row and is excluded).
    var rows = [];
    tableEl.querySelectorAll('.rdg-row').forEach(function (row) {
        var cells = row.querySelectorAll('[role="gridcell"]');
        rows.push(Array.prototype.map.call(cells, function (c) {
            return c.textContent.trim();
        }));
    });

    var esc = function (v) {
        if (v == null) return '';
        var s = String(v);
        return /[",\r\n;]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
    };

    // UTF-8 BOM + "sep=,\r\n" — same format Grafana's "Download for Excel" emits.
    var csv = '\uFEFF' + 'sep=,\r\n'
        + headers.map(esc).join(',') + '\r\n'
        + rows.map(function (r) { return r.map(esc).join(','); }).join('\r\n');

    var titleEl = panel.querySelector('[data-testid="header-container"]')
               || panel.querySelector('.panel-title-text')
               || panel.querySelector('h2, h6');
    var title = (titleEl ? titleEl.textContent : 'table').trim() || 'table';
    var fname = title.replace(/[^\w\-]+/g, '_')
        + '-' + new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-')
        + '.csv';

    var blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = fname;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 60000);

    window.resetUI();
};

window.updateExportOptions = function () {
    var $select = $('#cmbType');
    var hasCsv = $select.find('option[value="csv"]').length > 0;
    var count = window.findTablePanels().length;

    if (count === 1 && !hasCsv) {
        $select.append('<option value="csv">CSV</option>');
    } else if (count !== 1 && hasCsv) {
        $select.find('option[value="csv"]').remove();
        if ($select.val() === 'csv') $select.val('pdf_print');
    }
};

