// ---------- Button wiring ----------

$("#btnExport")
    .off('.upload')
    .on({
        'click.upload': function () {
            var type = $('#cmbType').val();
            window.startDown();
            if (type === 'csv') {
                try {
                    window.exportTableCSV();
                } catch (e) {
                    window.resetUI();
                    console.error('CSV export error:', e);
                    alert('CSV export failed:\n' + e.message);
                }
            } else {
                window.getPDF();
            }
        }
    });

// ---------- Init ----------

$(function () {
    var href = URL.parse(window.location.href);
    var entries = href.searchParams.entries();
    for (let n = entries.next(); !n.done; n = entries.next()) {
        let name = n.value[0];
        if (name == 'pdf-export') {
            $('#cmbType').parent().css({ 'display': 'none' });
            break;
        }
    }

    // Initial + delayed retries (panels render async)
    window.updateExportOptions();
    setTimeout(window.updateExportOptions, 1000);
    setTimeout(window.updateExportOptions, 3000);

    // React to panel DOM changes (viz type switch, panel add/remove, etc.)
    if (!window._bt_exportObserver) {
        window._bt_exportObserver = new MutationObserver(function () {
            clearTimeout(window._bt_exportTimer);
            window._bt_exportTimer = setTimeout(window.updateExportOptions, 400);
        });
        var root = document.querySelector('.react-grid-layout') || document.body;
        window._bt_exportObserver.observe(root, { childList: true, subtree: true });
    }
});

